import { useState, useCallback } from 'react';

export interface FilingStatus {
  r1: boolean;
  r3b: boolean;
}

const STORAGE_KEY = 'clientify_monthly_filing_v3';

export const FULL_YEAR_VAL = 'Full Year (Summary)';

// India FY sequence
export const FY_MONTHS = [
  'April', 'May', 'June', 'July', 'August', 'September', 
  'October', 'November', 'December', 'January', 'February', 'March'
];

export const FY_QUARTERS = [
  'April-June (Q1)',
  'July-September (Q2)',
  'October-December (Q3)',
  'January-March (Q4)'
];

const getDynamicYears = () => {
  const startYear = 2023;
  const now = new Date();
  const currentYear = now.getFullYear();
  const currentMonth = now.getMonth();
  const latestStartYear = currentMonth >= 3 ? currentYear : currentYear - 1;

  const list = [];
  for (let y = startYear; y <= latestStartYear; y++) {
    list.push(`${y}-${(y + 1).toString().slice(-2)}`);
  }
  return list.reverse(); // Latest first
};

export const YEARS = getDynamicYears();

export const MONTHS = [
  ...FY_MONTHS
];

export const QUARTERS = [
  ...FY_QUARTERS
];

export const getDefaultPeriod = () => {
  const now = new Date();
  const m = now.getMonth();
  const calYear = now.getFullYear();

  const getFY = (month: number, year: number) => {
    if (month >= 3) return `${year}-${(year + 1).toString().slice(-2)}`;
    return `${year - 1}-${year.toString().slice(-2)}`;
  };

  let prevMonthIdx = m - 1;
  let mYear = calYear;
  if (prevMonthIdx < 0) {
    prevMonthIdx = 11;
    mYear = calYear - 1;
  }

  const monthFY = getFY(prevMonthIdx, mYear);

  let qIdx = 0;
  let qYear = calYear;
  if (m >= 0 && m <= 2) { 
    qIdx = 2; 
  } else if (m >= 3 && m <= 5) { 
    qIdx = 3; 
    qYear = calYear - 1;
  } else if (m >= 6 && m <= 8) { 
    qIdx = 0; 
  } else { 
    qIdx = 1; 
  }

  const qStartMonths = [3, 6, 9, 0];
  const quarterFY = getFY(qStartMonths[qIdx], qYear);

  return { 
    month: MONTHS[prevMonthIdx], 
    quarter: QUARTERS[qIdx],
    year: monthFY,
    quarterYear: quarterFY
  };
};

export const useMonthlyFilingLogic = (selectedYear: string, selectedMonth: string) => {
  const [allData, setAllData] = useState<Record<string, Record<string, FilingStatus>>>(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    return saved ? JSON.parse(saved) : {};
  });

  const toggleStatus = useCallback((clientId: string, type: 'r1' | 'r3b', customPeriod?: string) => {
    const periodKey = customPeriod || `${selectedYear}_${selectedMonth}`;
    setAllData(prev => {
      const periodData = { ...(prev[periodKey] || {}) };
      const clientData = { ...(periodData[clientId] || { r1: false, r3b: false }) };
      clientData[type] = !clientData[type];
      periodData[clientId] = clientData;
      const next = { ...prev, [periodKey]: periodData };
      localStorage.setItem(STORAGE_KEY, JSON.stringify(next));
      return next;
    });
  }, [selectedYear, selectedMonth]);

  const getStatus = useCallback((clientId: string, customPeriod?: string): FilingStatus => {
    const periodKey = customPeriod || `${selectedYear}_${selectedMonth}`;
    return (allData[periodKey] || {})[clientId] || { r1: false, r3b: false };
  }, [allData, selectedYear, selectedMonth]);

  return { getStatus, toggleStatus };
};

import React, { useState, useEffect, useMemo } from 'react';
import { Client } from '../../../types';
import { mockBackend } from '../../../services/mockBackend';
import GSTClientFormModal from '../../Clientform/GSTClientFormModal';
import Loader from '../../../components/Loader';
import { useMonthlyFilingLogic, MONTHS, YEARS, getDefaultPeriod, FULL_YEAR_VAL, FY_MONTHS } from './filinglogic/MonthlyFilingLogic';

const MonthlyFiling: React.FC = () => {
  const defaultPeriod = getDefaultPeriod();
  const [clients, setClients] = useState<Client[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [selectedYear, setSelectedYear] = useState(defaultPeriod.year);
  const [selectedMonth, setSelectedMonth] = useState(defaultPeriod.month);

  const [r1Filter, setR1Filter] = useState<'All' | 'Filed' | 'Pending'>('All');
  const [r3bFilter, setR3bFilter] = useState<'All' | 'Filed' | 'Pending'>('All');
  const [activeHeaderFilter, setActiveHeaderFilter] = useState<'r1' | 'r3b' | null>(null);

  const [selectedClient, setSelectedClient] = useState<Client | null>(null);
  const [isDetailModalOpen, setIsDetailModalOpen] = useState(false);
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);

  const [showPassInView, setShowPassInView] = useState(false);
  const [isEditingPassword, setIsEditingPassword] = useState(false);
  const [localPassValue, setLocalPassValue] = useState('');

  const [visiblePasswords, setVisiblePasswords] = useState<Set<string>>(new Set());
  const [editingPasswordId, setEditingPasswordId] = useState<string | null>(null);
  const [newPasswordValue, setNewPasswordValue] = useState('');

  const { getStatus, toggleStatus } = useMonthlyFilingLogic(selectedYear, selectedMonth);

  const isFullYearView = selectedMonth === FULL_YEAR_VAL;

  const fetchClients = async () => {
    setIsLoading(true);
    try {
      const data = await mockBackend.getClients();
      const filtered = data.filter(c => 
        c.status === 'Active Filing' && 
        c.gstProfile?.regType === 'Regular' &&
        c.gstProfile?.filingFreq === 'Monthly' &&
        (c.gstProfile?.gstStatus === 'Active' || c.gstProfile?.gstStatus === 'Suspended')
      );
      setClients(filtered);
    } finally { setIsLoading(false); }
  };

  useEffect(() => { fetchClients(); }, []);

  const formatDate = (dateStr?: string) => {
    if (!dateStr) return 'N/A';
    if (!dateStr.includes('-')) return dateStr;
    const parts = dateStr.split('-');
    if (parts[0].length === 4) return `${parts[2]}-${parts[1]}-${parts[0]}`;
    return dateStr;
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
  };

  const shareViaWhatsApp = (text: string) => {
    const url = `https://api.whatsapp.com/send?text=${encodeURIComponent(text)}`;
    window.open(url, '_blank');
  };

  const getCredText = (client: Client) => `*GST Credentials for ${client.tradeName || client.legalName}*\n\n*GSTIN:* ${client.gstProfile?.gstin}\n*Username:* ${client.gstProfile?.username}\n*Password:* ${client.gstProfile?.password}\n\n_Shared via Clientify_`;

  const saveQuickPassword = async (client: Client) => {
    try {
      const updated = { ...client, gstProfile: { ...client.gstProfile!, password: newPasswordValue } };
      await mockBackend.saveClient(updated);
      setClients(prev => prev.map(c => c.id === client.id ? (updated as Client) : c));
      setEditingPasswordId(null);
    } catch (err) { alert("Update failed"); }
  };

  const filteredClients = useMemo(() => {
    let list = clients.filter(c => 
      (c.legalName || '').toLowerCase().includes(search.toLowerCase()) || 
      (c.tradeName || '').toLowerCase().includes(search.toLowerCase()) || 
      (c.gstProfile?.gstin || '').toLowerCase().includes(search.toLowerCase())
    );
    if (!isFullYearView) {
      if (r1Filter !== 'All') list = list.filter(c => r1Filter === 'Filed' ? getStatus(c.id).r1 : !getStatus(c.id).r1);
      if (r3bFilter !== 'All') list = list.filter(c => r3bFilter === 'Filed' ? getStatus(c.id).r3b : !getStatus(c.id).r3b);
    }
    return list;
  }, [clients, search, r1Filter, r3bFilter, getStatus, isFullYearView]);

  const stats = useMemo(() => {
    const total = filteredClients.length;
    if (isFullYearView) return { total, r1Filed: 'N/A', r3bFiled: 'N/A' };
    const r1Filed = filteredClients.filter(c => getStatus(c.id).r1).length;
    const r3bFiled = filteredClients.filter(c => getStatus(c.id).r3b).length;
    return { total, r1Filed, r3bFiled };
  }, [filteredClients, getStatus, isFullYearView]);

  const handleExport = () => {
    const headers = isFullYearView 
      ? ["S.No", "Trade Name", "Legal Name", "GSTIN", ...FY_MONTHS.flatMap(m => [`${m} R1`, `${m} 3B`])]
      : ["S.No", "Trade Name", "Legal Name", "GSTIN", "User ID", "Password", "GSTR-1", "GSTR-3B"];

    const rows = filteredClients.map((c, i) => {
      if (isFullYearView) {
        const monthStatuses = FY_MONTHS.flatMap(m => {
          const st = getStatus(c.id, `${selectedYear}_${m}`);
          return [st.r1 ? 'FILED' : 'PENDING', st.r3b ? 'FILED' : 'PENDING'];
        });
        return [i + 1, c.tradeName, c.legalName, c.gstProfile?.gstin, ...monthStatuses].join(",");
      }
      return [
        i + 1, c.tradeName, c.legalName, c.gstProfile?.gstin, c.gstProfile?.username, c.gstProfile?.password,
        getStatus(c.id).r1 ? "FILED" : "PENDING", getStatus(c.id).r3b ? "FILED" : "PENDING"
      ].join(",");
    }).join("\n");

    const link = document.createElement('a');
    link.href = URL.createObjectURL(new Blob([headers.join(",") + "\n" + rows], { type: 'text/csv' }));
    link.download = `Monthly_Filing_${selectedMonth}_${selectedYear}.csv`;
    link.click();
