                                <button onClick={() => toggleStatus(client.id, 'r3b', pKey)} className={`h-2.5 w-2.5 rounded-full transition-all ${st.r3b ? 'bg-indigo-500 shadow-[0_0_8px_rgba(79,70,229,0.4)]' : 'bg-slate-200'}`} title={`${m}: GSTR-3B`} />
