import React, { useState, useEffect, useMemo } from 'react';
import { Client } from '../../../types';
import { mockBackend } from '../../../services/mockBackend';
import GSTClientFormModal from '../../Clientform/GSTClientFormModal';
import Loader from '../../../components/Loader';
import { useQuarterlyFilingLogic } from './filinglogic/QuarterlyFilingLogic';
import { getDefaultPeriod, YEARS, QUARTERS, FULL_YEAR_VAL, FY_QUARTERS } from './filinglogic/MonthlyFilingLogic';

const QuarterlyFiling: React.FC = () => {
  const defaultPeriod = getDefaultPeriod();
  const [clients, setClients] = useState<Client[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [selectedYear, setSelectedYear] = useState(defaultPeriod.year);
  const [selectedQuarter, setSelectedQuarter] = useState(defaultPeriod.quarter);

  const [r1Filter, setR1Filter] = useState<'All' | 'Filed' | 'Pending'>('All');
  const [r3bFilter, setR3bFilter] = useState<'All' | 'Filed' | 'Pending'>('All');
  const [activeHeaderFilter, setActiveHeaderFilter] = useState<'r1' | 'r3b' | null>(null);

  const [selectedClient, setSelectedClient] = useState<Client | null>(null);
  const [isDetailModalOpen, setIsDetailModalOpen] = useState(false);
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);

  const [visiblePasswords, setVisiblePasswords] = useState<Set<string>>(new Set());

  const { getStatus, toggleStatus } = useQuarterlyFilingLogic(selectedYear, selectedQuarter);

  const isFullYearView = selectedQuarter === FULL_YEAR_VAL;

  const fetchClients = async () => {
    setIsLoading(true);
    try {
      const data = await mockBackend.getClients();
      const filtered = data.filter(c => 
        c.status === 'Active Filing' && 
        c.gstProfile?.regType === 'Regular' &&
        c.gstProfile?.filingFreq === 'Quarterly' &&
        (c.gstProfile?.gstStatus === 'Active' || c.gstProfile?.gstStatus === 'Suspended')
      );
      setClients(filtered);
    } finally { setIsLoading(false); }
  };

  useEffect(() => { fetchClients(); }, []);

  const filteredClients = useMemo(() => {
    let list = clients.filter(c => 
      (c.legalName || '').toLowerCase().includes(search.toLowerCase()) || 
      (c.tradeName || '').toLowerCase().includes(search.toLowerCase()) || 
      (c.gstProfile?.gstin || '').toLowerCase().includes(search.toLowerCase())
    );
    if (!isFullYearView) {
      if (r1Filter !== 'All') list = list.filter(c => r1Filter === 'Filed' ? getStatus(c.id).r1 : !getStatus(c.id).r1);
      if (r3bFilter !== 'All') list = list.filter(c => r3bFilter === 'Filed' ? getStatus(c.id).r3b : !getStatus(c.id).r3b);
    }
    return list;
  }, [clients, search, r1Filter, r3bFilter, getStatus, isFullYearView]);

  const handleExport = () => {
    const headers = isFullYearView 
      ? ["S.No", "Trade Name", "Legal Name", "GSTIN", ...FY_QUARTERS.flatMap(q => [`${q} R1`, `${q} 3B`])]
      : ["S.No", "Trade Name", "Legal Name", "GSTIN", "User ID", "Password", "IFF/GSTR-1", "GSTR-3B"];

    const rows = filteredClients.map((c, i) => {
      if (isFullYearView) {
        const quarterStatuses = FY_QUARTERS.flatMap(q => {
          const st = getStatus(c.id, `${selectedYear}_${q}`);
          return [st.r1 ? 'FILED' : 'PENDING', st.r3b ? 'FILED' : 'PENDING'];
        });
        return [i + 1, c.tradeName, c.legalName, c.gstProfile?.gstin, ...quarterStatuses].join(",");
      }
      const st = getStatus(c.id);
      return [i + 1, c.tradeName, c.legalName, c.gstProfile?.gstin, c.gstProfile?.username, c.gstProfile?.password, st.r1 ? "FILED" : "PENDING", st.r3b ? "FILED" : "PENDING"].join(",");
    }).join("\n");

    const link = document.createElement('a');
    link.href = URL.createObjectURL(new Blob([headers.join(",") + "\n" + rows], { type: 'text/csv' }));
    link.download = `Quarterly_Filing_${selectedQuarter}_${selectedYear}.csv`;
    link.click();
  };

  if (isLoading) return <Loader />;

  return (
    <div className="flex flex-col h-full space-y-4 animate-in fade-in duration-500 max-w-full mx-auto w-full overflow-hidden">

      <div className="flex flex-col lg:flex-row items-center gap-4 bg-white p-3 rounded-[1.5rem] border border-slate-200 shadow-sm shrink-0">
        <div className="flex items-center gap-6 px-4 border-r border-slate-100 hidden md:flex shrink-0">
          <div className="text-center"><p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Entity Count</p><p className="text-xl font-black text-slate-900 leading-none">{filteredClients.length}</p></div>
        </div>

        <div className="relative flex-1 w-full group">
          <input type="text" placeholder="Search QRMP client..." value={search} onChange={e => setSearch(e.target.value)}
            className="w-full bg-slate-50 border-none rounded-xl py-3 pl-12 pr-4 font-bold text-sm text-slate-900 focus:ring-2 focus:ring-indigo-600/10 outline-none" />
          <svg className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
        </div>

        <div className="flex items-center gap-2 shrink-0">
          <select value={selectedYear} onChange={e => setSelectedYear(e.target.value)} className="bg-slate-50 border-none rounded-xl px-4 py-3 text-[11px] font-black uppercase tracking-widest text-slate-600 outline-none cursor-pointer">{YEARS.map(y => <option key={y} value={y}>{y}</option>)}</select>
          <select value={selectedQuarter} onChange={e => setSelectedQuarter(e.target.value)} className="bg-indigo-50 border-none rounded-xl px-4 py-3 text-[11px] font-black uppercase tracking-widest text-indigo-600 outline-none cursor-pointer">
            <option value={FULL_YEAR_VAL}>{FULL_YEAR_VAL}</option>
            {QUARTERS.map(q => <option key={q} value={q}>{q}</option>)}
          </select>
          <button onClick={handleExport} className="h-11 w-11 flex items-center justify-center bg-slate-900 text-white rounded-xl shadow-lg hover:bg-emerald-600 transition-all"><svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg></button>
        </div>
      </div>

      <div className="flex-1 bg-white rounded-[2rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col">
        <div className="overflow-x-auto no-scrollbar flex-1">
          <table className={`w-full text-left border-collapse table-fixed ${isFullYearView ? 'min-w-[1200px]' : 'min-w-[1250px]'}`}>
            <thead className="sticky top-0 z-20">
              <tr className="bg-slate-50 border-b border-slate-100">
                <th className="px-4 py-5 text-[12px] font-black uppercase tracking-widest text-slate-400 w-[60px]">S.No</th>
                <th className="px-4 py-5 text-[12px] font-black uppercase tracking-widest text-slate-400 w-[180px]">Trade Name</th>
                <th className="px-4 py-5 text-[12px] font-black uppercase tracking-widest text-slate-400 w-[180px]">Legal Name</th>
                <th className="px-4 py-5 text-[12px] font-black uppercase tracking-widest text-slate-400 w-[200px]">GSTIN</th>

                {isFullYearView ? (
                   FY_QUARTERS.map(q => (
                    <th key={q} className="px-4 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400 text-center border-l border-slate-100/50">
                      {q.split('(')[1].replace(')', '')}
                      <div className="flex justify-center gap-3 mt-1 text-[8px] opacity-60"><span>R1</span><span>3B</span></div>
                    </th>
                   ))
                ) : (
                  <>
                    <th className="px-4 py-5 text-[12px] font-black uppercase tracking-widest text-slate-400 text-center w-[110px] relative">
                      <button onClick={() => setActiveHeaderFilter(activeHeaderFilter === 'r1' ? null : 'r1')} className="flex items-center justify-center gap-1 w-full uppercase">
                        IFF/GSTR-1 <svg className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M19 9l-7 7-7-7" /></svg>
                      </button>
                      {activeHeaderFilter === 'r1' && (
                        <div className="absolute top-full left-0 mt-1 w-32 bg-white border border-slate-200 rounded-xl shadow-xl z-50 p-1 animate-in zoom-in-95">
                          {['All', 'Filed', 'Pending'].map(f => <button key={f} onClick={() => { setR1Filter(f as any); setActiveHeaderFilter(null); }} className={`w-full text-left px-3 py-2 text-[10px] font-black uppercase rounded-lg ${r1Filter === f ? 'bg-indigo-600 text-white' : 'hover:bg-slate-50'}`}>{f}</button>)}
                        </div>
                      )}
                    </th>
                    <th className="px-4 py-5 text-[12px] font-black uppercase tracking-widest text-slate-400 text-center w-[110px] relative">
                      <button onClick={() => setActiveHeaderFilter(activeHeaderFilter === 'r3b' ? null : 'r3b')} className="flex items-center justify-center gap-1 w-full uppercase">
                        GSTR-3B <svg className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M19 9l-7 7-7-7" /></svg>
                      </button>
                      {activeHeaderFilter === 'r3b' && (
                        <div className="absolute top-full left-0 mt-1 w-32 bg-white border border-slate-200 rounded-xl shadow-xl z-50 p-1 animate-in zoom-in-95">
                          {['All', 'Filed', 'Pending'].map(f => <button key={f} onClick={() => { setR3bFilter(f as any); setActiveHeaderFilter(null); }} className={`w-full text-left px-3 py-2 text-[10px] font-black uppercase rounded-lg ${r3bFilter === f ? 'bg-indigo-600 text-white' : 'hover:bg-slate-50'}`}>{f}</button>)}
                        </div>
                      )}
                    </th>
                    <th className="px-4 py-5 text-[12px] font-black uppercase tracking-widest text-slate-400 w-[140px]">User ID</th>
                    <th className="px-4 py-5 text-[12px] font-black uppercase tracking-widest text-slate-400 w-[180px]">Password</th>
                  </>
                )}
                <th className="px-4 py-5 text-[12px] font-black uppercase tracking-widest text-slate-400 text-right w-[80px]">Action</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredClients.map((client, idx) => {
                return (
                  <tr key={client.id} className="group hover:bg-slate-50/50 transition-all">
                    <td className="px-4 py-5 text-[11px] font-black text-slate-300">{(idx + 1).toString().padStart(2, '0')}</td>
                    <td className="px-4 py-5 text-[11px] font-black text-slate-900 uppercase truncate">{client.tradeName || '---'}</td>
                    <td className="px-4 py-5 text-[11px] font-bold text-slate-500 uppercase truncate">{client.legalName}</td>
                    <td className="px-4 py-5"><span className="text-[11px] font-black text-indigo-600 font-mono tracking-widest">{client.gstProfile?.gstin}</span></td>

                    {isFullYearView ? (
                      FY_QUARTERS.map(q => {
                        const pKey = `${selectedYear}_${q}`;
                        const st = getStatus(client.id, pKey);
                        return (
                          <td key={q} className="px-4 py-5 border-l border-slate-50 text-center">
                             <div className="flex items-center justify-center gap-4">
                                <button onClick={() => toggleStatus(client.id, 'r1', pKey)} className={`h-3 w-3 rounded-full transition-all ${st.r1 ? 'bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.4)]' : 'bg-slate-200'}`} />
                                <button onClick={() => toggleStatus(client.id, 'r3b', pKey)} className={`h-3 w-3 rounded-full transition-all ${st.r3b ? 'bg-indigo-500 shadow-[0_0_8px_rgba(79,70,229,0.4)]' : 'bg-slate-200'}`} />
                             </div>
                          </td>
                        );
                      })
                    ) : (
                      <>
                        <td className="px-4 py-5 text-center">
                           <button onClick={() => toggleStatus(client.id, 'r1')} className={`px-3 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest transition-all ${getStatus(client.id).r1 ? 'bg-emerald-100 text-emerald-700' : 'bg-slate-100 text-slate-400 hover:bg-slate-200'}`}>
                             {getStatus(client.id).r1 ? 'Filed' : 'Pending'}</button>
