                   <h4 className="text-[10px] font-black uppercase tracking-[0.3em] text-indigo-600 flex items-center gap-2">Registration Profile <div className="h-px flex-1 bg-slate-100" /></h4>
                   <div className="space-y-4">
                      <div className="flex justify-between border-b border-slate-50 pb-2"><span className="text-[9px] font-black uppercase text-slate-400">GSTIN</span><span className="text-sm font-black text-indigo-600 font-mono">{selectedClient.gstProfile?.gstin}</span></div>
