import React, { useState, useEffect, useMemo } from 'react';
import { Client } from '../../../types';
import { mockBackend } from '../../../services/mockBackend';
import GSTClientFormModal from '../../Clientform/GSTClientFormModal';
import Loader from '../../../components/Loader';
import { useGSTR4Logic } from './GSTR4logic';
import { YEARS, FY_QUARTERS } from '../GSTReturn/filinglogic/MonthlyFilingLogic';

const GSTR4: React.FC = () => {
  // Logic to determine the default previous Financial Year
  const getPreviousFY = () => {
    const now = new Date();
    const currentMonth = now.getMonth(); // 0-11
    const currentYear = now.getFullYear();
    // If we are in Apr-Dec 2025, current FY is 2025-26. Prev is 2024-25.
    // If we are in Jan-Mar 2025, current FY is 2024-25. Prev is 2023-24.
    const startYear = currentMonth >= 3 ? currentYear - 1 : currentYear - 2;
    return `${startYear}-${(startYear + 1).toString().slice(-2)}`;
  };

  const [clients, setClients] = useState<Client[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [selectedYear, setSelectedYear] = useState(getPreviousFY());

  const [statusFilter, setStatusFilter] = useState<'All' | 'Filed' | 'Pending'>('All');
  const [isFilterMenuOpen, setIsFilterMenuOpen] = useState(false);

  const [selectedClient, setSelectedClient] = useState<Client | null>(null);
  const [isDetailModalOpen, setIsDetailModalOpen] = useState(false);
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [visiblePasswords, setVisiblePasswords] = useState<Set<string>>(new Set());

  const { getStatus, toggleStatus } = useGSTR4Logic(selectedYear);

  // Fetch CMP-08 data directly from its storage for the summary column
  const cmp08Data = useMemo(() => {
    const saved = localStorage.getItem('clientify_composition_filing_v3');
    return saved ? JSON.parse(saved) : {};
  }, [selectedYear]);

  const fetchClients = async () => {
    setIsLoading(true);
    try {
      const data = await mockBackend.getClients();
      const filtered = data.filter(c => 
        c.gstProfile?.regType === 'Composition' &&
        (c.gstProfile?.gstStatus === 'Active' || c.gstProfile?.gstStatus === 'Suspended')
      );
      setClients(filtered);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchClients();
  }, []);

  const filteredClients = useMemo(() => {
    let list = clients.filter(c => 
      (c.legalName || '').toLowerCase().includes(search.toLowerCase()) || 
      (c.tradeName || '').toLowerCase().includes(search.toLowerCase()) || 
      (c.gstProfile?.gstin || '').toLowerCase().includes(search.toLowerCase())
    );

    if (statusFilter !== 'All') {
      list = list.filter(c => statusFilter === 'Filed' ? getStatus(c.id).filed : !getStatus(c.id).filed);
    }
    return list;
  }, [clients, search, statusFilter, getStatus]);

  const stats = useMemo(() => {
    const total = filteredClients.length;
    const filedCount = filteredClients.filter(c => getStatus(c.id).filed).length;
    return { total, filedCount };
  }, [filteredClients, getStatus]);

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
  };

  const handleExport = () => {
    const headers = ["S.No", "Trade Name", "Legal Name", "GSTIN", "User ID", "Password", "CMP-08 Q1", "CMP-08 Q2", "CMP-08 Q3", "CMP-08 Q4", "GSTR-4 Status", "Filing Date"].join(",");
    const rows = filteredClients.map((c, i) => {
      const st = getStatus(c.id);
      const qStatus = FY_QUARTERS.map(q => {
        const periodKey = `${selectedYear}_${q}`;
        return (cmp08Data[periodKey]?.[c.id]?.cmp08) ? "FILED" : "PENDING";
      });
      return [
        i + 1, c.tradeName, c.legalName, c.gstProfile?.gstin, c.gstProfile?.username, c.gstProfile?.password,
        ...qStatus, st.filed ? "FILED" : "PENDING", st.date || "N/A"
      ].join(",");
    }).join("\n");

    const link = document.createElement('a');
    link.href = URL.createObjectURL(new Blob([headers + "\n" + rows], { type: 'text/csv' }));
    link.download = `GSTR4_Annual_Return_${selectedYear}.csv`;
    link.click();
  };

  if (isLoading) return <Loader />;

  return (
    <div className="flex flex-col h-full space-y-4 animate-in fade-in duration-500 max-w-full mx-auto w-full overflow-hidden">

      {/* Dynamic Header Toolbar */}
      <div className="flex flex-col lg:flex-row items-center gap-4 bg-white p-3 rounded-[1.5rem] border border-slate-200 shadow-sm shrink-0">
        <div className="flex items-center gap-6 px-4 border-r border-slate-100 hidden md:flex shrink-0">
          <div className="text-center">
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">FY {selectedYear}</p>
            <p className="text-xl font-black text-slate-900 leading-none">{stats.total}</p>
          </div>
          <div className="text-center border-l border-slate-100 pl-6">
            <p className="text-[9px] font-black text-emerald-500 uppercase tracking-widest mb-1">GSTR-4 Filed</p>
            <p className="text-xl font-black text-emerald-600 leading-none">{stats.filedCount}</p>
          </div>
        </div>

        <div className="relative flex-1 w-full group">
          <input type="text" placeholder="Search composition entity or GSTIN..." value={search} onChange={e => setSearch(e.target.value)}
            className="w-full bg-slate-50 border-none rounded-xl py-3 pl-12 pr-4 font-bold text-sm text-slate-900 focus:ring-2 focus:ring-indigo-600/10 outline-none transition-all" />
          <svg className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-slate-400 group-focus-within:text-indigo-600 transition-colors" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
        </div>

        <div className="flex items-center gap-2 shrink-0">
          <div className="flex bg-slate-50 rounded-xl p-1">
             <select value={selectedYear} onChange={e => setSelectedYear(e.target.value)} 
               className="bg-transparent border-none rounded-lg px-4 py-2 text-[11px] font-black uppercase tracking-widest text-slate-600 outline-none cursor-pointer">
               {YEARS.map(y => <option key={y} value={y}>FY {y}</option>)}
             </select>
          </div>
          <button onClick={handleExport} className="h-11 w-11 flex items-center justify-center bg-slate-900 text-white rounded-xl shadow-lg hover:bg-emerald-600 transition-all" title="Export to CSV">
            <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
          </button>
        </div>
      </div>

      {/* Main Matrix Content */}
      <div className="flex-1 bg-white rounded-[2rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col">
        <div className="overflow-x-auto no-scrollbar flex-1">
          <table className="w-full text-left border-collapse table-fixed min-w-[1350px]">
            <thead className="sticky top-0 z-20">
              <tr className="bg-slate-50 border-b border-slate-100">
                <th className="px-4 py-5 text-[12px] font-black uppercase tracking-widest text-slate-400 w-[60px]">S.No</th>
                <th className="px-4 py-5 text-[12px] font-black uppercase tracking-widest text-slate-400 w-[160px]">Trade Name</th>
                <th className="px-4 py-5 text-[12px] font-black uppercase tracking-widest text-slate-400 w-[180px]">Legal Name</th>
                <th className="px-4 py-5 text-[12px] font-black uppercase tracking-widest text-slate-400 w-[190px]">GSTIN</th>

                <th className="px-4 py-5 text-[12px] font-black uppercase tracking-widest text-slate-400 text-center w-[160px]">
                  CMP-08 Summary
                  <div className="flex justify-center gap-3 mt-1 text-[8px] opacity-60"><span>Q1</span><span>Q2</span><span>Q3</span><span>Q4</span></div>
                </th>

                <th className="px-4 py-5 text-[12px] font-black uppercase tracking-widest text-slate-400 text-center w-[140px] relative">
                  <button onClick={() => setIsFilterMenuOpen(!isFilterMenuOpen)} className="flex items-center justify-center gap-1 w-full uppercase">
                    GSTR-4 Status <svg className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M19 9l-7 7-7-7" /></svg>
                  </button>
                  {isFilterMenuOpen && (
                    <div className="absolute top-full left-1/2 -translate-x-1/2 mt-1 w-32 bg-white border border-slate-200 rounded-xl shadow-xl z-50 p-1 animate-in zoom-in-95">
                      {['All', 'Filed', 'Pending'].map(f => (
                        <button key={f} onClick={() => { setStatusFilter(f as any); setIsFilterMenuOpen(false); }} 
                          className={`w-full text-left px-3 py-2 text-[10px] font-black uppercase rounded-lg transition-colors ${statusFilter === f ? 'bg-indigo-600 text-white' : 'hover:bg-slate-50 text-slate-600'}`}>
                          {f}
                        </button>
                      ))}
                    </div>
                  )}
                </th>

                <th className="px-4 py-5 text-[12px] font-black uppercase tracking-widest text-slate-400 w-[130px]">User ID</th>
                <th className="px-4 py-5 text-[12px] font-black uppercase tracking-widest text-slate-400 w-[160px]">Password</th>
