                <section className="space-y-6">
                   <h4 className="text-[10px] font-black uppercase tracking-[0.3em] text-indigo-600 flex items-center gap-2">Portal Access <div className="h-px flex-1 bg-slate-100" /></h4>
                   <div className="bg-slate-50 p-6 rounded-3xl space-y-4">
