            <thead className="sticky top-0 z-20">
              <tr className="bg-slate-50 border-b border-slate-100">
                <th className="px-4 py-5 text-[12px] font-black uppercase tracking-widest text-slate-400 w-[60px]">S.No</th>
                <th className="px-4 py-5 text-[12px] font-black uppercase tracking-widest text-slate-400 w-[180px]">Trade Name</th>
                <th className="px-4 py-5 text-[12px] font-black uppercase tracking-widest text-slate-400 w-[200px]">GSTIN</th>

                <th className="px-4 py-5 text-[12px] font-black uppercase tracking-widest text-slate-400 text-center w-[120px]">GSTR-9 Status</th>
                <th className="px-4 py-5 text-[12px] font-black uppercase tracking-widest text-slate-400 text-center w-[120px]">GSTR-9C Status</th>

                <th className="px-4 py-5 text-[12px] font-black uppercase tracking-widest text-slate-400 w-[140px]">User ID</th>
                <th className="px-4 py-5 text-[12px] font-black uppercase tracking-widest text-slate-400 w-[180px]">Password</th>
                <th className="px-4 py-5 text-[12px] font-black uppercase tracking-widest text-slate-400 text-right w-[120px]">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredDisplayList.length === 0 ? (
                <tr>
                  <td colSpan={8} className="py-32 text-center">
                    <div className="flex flex-col items-center">
                      <div className="h-20 w-20 bg-slate-50 rounded-full flex items-center justify-center text-slate-200 mb-4">
                        <svg className="h-10 w-10" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" /></svg>
                      </div>
                      <p className="text-sm font-black uppercase tracking-[0.2em] text-slate-400">No entities added to GSTR-9 watchlist</p>
                      <button onClick={() => setIsAddModalOpen(true)} className="mt-4 text-indigo-600 font-black uppercase text-[10px] tracking-widest hover:underline">+ Add Regular Client to Track</button>
                    </div>
                  </td>
                </tr>
              ) : (
                filteredDisplayList.map((client, idx) => {
                  const status = getStatus(client.id);
                  const isPassVisible = visiblePasswords.has(client.id);

                  return (
                    <tr key={client.id} className="group hover:bg-slate-50/50 transition-all">
                      <td className="px-4 py-5 text-[11px] font-black text-slate-300">{(idx + 1).toString().padStart(2, '0')}</td>
                      <td className="px-4 py-5">
                        <p className="text-[11px] font-black text-slate-900 uppercase truncate" title={client.tradeName}>{client.tradeName || client.legalName || '---'}</p>
                        <p className="text-[9px] font-bold text-slate-400 uppercase truncate">{client.legalName}</p>
                      </td>
                      <td className="px-4 py-5">
                         <div className="flex items-center gap-2 group/gstin">
                            <span className="text-[11px] font-black text-indigo-600 font-mono tracking-widest">{client.gstProfile?.gstin}</span>
                            <button onClick={() => { copyToClipboard(client.gstProfile?.gstin || ''); window.open('https://services.gst.gov.in/services/searchtp', '_blank'); }} 
                               className="h-6 w-6 rounded bg-indigo-50 text-indigo-600 hover:bg-indigo-600 hover:text-white transition-all flex items-center justify-center opacity-0 group-hover/gstin:opacity-100">
                               <svg className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
                            </button>
                         </div>
                      </td>

                      <td className="px-4 py-5 text-center">
                         <button onClick={() => toggleStatus(client.id, 'gstr9')} className={`px-4 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest transition-all ${status.gstr9 ? 'bg-emerald-100 text-emerald-700 shadow-sm' : 'bg-slate-100 text-slate-400 hover:bg-slate-200'}`}>
                           {status.gstr9 ? 'Filed' : 'Pending'}
                         </button>
                         {status.gstr9 && status.gstr9Date && <p className="text-[8px] font-black text-slate-300 mt-1 uppercase">{status.gstr9Date}</p>}
                      </td>

                      <td className="px-4 py-5 text-center">
                         <button onClick={() => toggleStatus(client.id, 'gstr9c')} className={`px-4 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest transition-all ${status.gstr9c ? 'bg-indigo-100 text-indigo-700 shadow-sm' : 'bg-slate-100 text-slate-400 hover:bg-slate-200'}`}>
                           {status.gstr9c ? 'Filed' : 'Pending'}
                         </button>
                         {status.gstr9c && status.gstr9cDate && <p className="text-[8px] font-black text-slate-300 mt-1 uppercase">{status.gstr9cDate}</p>}
                      </td>

                      <td className="px-4 py-5">
                        <p className="text-[11px] font-black text-slate-700 truncate">{client.gstProfile?.username}</p>
                      </td>

                      <td className="px-4 py-5">
                        <div className="flex items-center gap-2 group/pass">
                           <span className="text-[11px] font-black text-indigo-600 tracking-wider truncate max-w-[80px]">{isPassVisible ? client.gstProfile?.password : '••••••••'}</span>
                           <button onClick={() => setVisiblePasswords(prev => { const n = new Set(prev); n.has(client.id) ? n.delete(client.id) : n.add(client.id); return n; })} className="p-1 text-slate-300 hover:text-indigo-600 transition-colors">
                              {isPassVisible ? <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13.875 18.825A10.05 10.05 0 0112 19c-4.478 0-8.268-2.943-9.543-7a9.97 9.97 0 011.563-3.029m5.858.908a3 3 0 114.243 4.243M9.878 9.878l4.242 4.242M9.88 9.88l-3.29-3.29m7.532 7.532l3.29 3.29M3 3l18 18" /></svg> : <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7S1.732 16.057.458 10z" /></svg>}
                           </button>
                           <button onClick={() => { setSelectedClient(client); setIsEditModalOpen(true); }} className="p-1 text-slate-300 hover:text-amber-600 transition-colors opacity-0 group-hover/pass:opacity-100">
                             <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" /></svg>
                           </button>
                        </div>
                      </td>

                      <td className="px-4 py-5 text-right whitespace-nowrap">
                        <div className="flex items-center justify-end gap-2">
                           <button onClick={() => { copyToClipboard(client.gstProfile?.username || ''); window.open('https://services.gst.gov.in/services/login', '_blank'); }} className="h-8 w-8 rounded-lg bg-slate-50 text-slate-400 hover:text-indigo-600 hover:bg-white transition-all flex items-center justify-center">
                              <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M11 16l-4-4m0 0l4-4m-4 4h14m-5 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" /></svg>
                           </button>
                           <button onClick={() => { setSelectedClient(client); setIsDetailModalOpen(true); }} className="h-8 w-8 rounded-lg bg-slate-50 text-slate-400 hover:text-indigo-600 hover:bg-white transition-all flex items-center justify-center">
                             <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7S1.732 16.057.458 10z" /></svg>
                           </button>
                           <button onClick={() => { if(confirm(`Remove ${client.tradeName || client.legalName} fromwatchlist?\nHistorical data will be preserved.`)) removeFromWatchlist(client.id); }} className="h-8 w-8 rounded-lg bg-slate-50 text-slate-400 hover:text-red-600 hover:bg-red-50 transition-all flex items-center justify-center">
                              <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                           </button>
                        </div>
                      </td>
                    </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* ADD CLIENT MODAL */}
      {isAddModalOpen && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center bg-slate-900/60 backdrop-blur-md p-4 animate-in fade-in duration-200">
           <div className="w-full max-w-xl bg-white rounded-[2.5rem] shadow-2xl flex flex-col max-h-[80vh] overflow-hidden animate-in zoom-in-95">
              <div className="px-8 py-6 border-b border-slate-100 flex items-center justify-between shrink-0">
                 <h3 className="text-xl font-black text-slate-900 uppercase tracking-tight">Add Client to Tracking</h3>
                 <button onClick={() => setIsAddModalOpen(false)} className="h-10 w-10 flex items-center justify-center rounded-xl hover:bg-slate-100">
                    <svg className="h-6 w-6 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6" /></svg>
                 </button>
              </div>

              <div className="p-6 shrink-0 bg-slate-50 border-b border-slate-100">
                 <div className="relative">
                    <input autoFocus type="text" placeholder="Search Regular taxpayers by name or GSTIN..." value={addSearch} onChange={e => setAddSearch(e.target.value)}
                      className="w-full bg-white border border-slate-200 rounded-xl py-3 pl-10 pr-4 font-bold text-sm outline-none focus:ring-4 focus:ring-indigo-50" />
                    <svg className="absolute left-3.5 top-1/2 -translate-y-1/2 h-4.5 w-4.5 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
                 </div>
              </div>

              <div className="flex-1 overflow-y-auto p-4 space-y-2 no-scrollbar">
                 {clientsAvailableToAdd.length === 0 ? (
                    <div className="py-12 text-center">
                       <p className="text-xs font-black uppercase text-slate-400 tracking-widest">No matching Regular clients found</p>
                    </div>
                 ) : (
                    clientsAvailableToAdd.map(c => (
                       <button key={c.id} onClick={() => { addToWatchlist(c.id); setIsAddModalOpen(false); }}
                         className="w-full flex items-center justify-between p-4 bg-white border border-slate-100 rounded-2xl hover:border-indigo-600 hover:bg-indigo-50/50 transition-all text-left">
                          <div>
                             <p className="text-[11px] font-black text-slate-900 uppercase truncate">{c.tradeName || c.legalName}</p>
                             <p className="text-[9px] font-black text-indigo-600 font-mono tracking-widest">{c.gstProfile?.gstin}</p>
                          </div>
                          <div className="h-8 w-8 rounded-full bg-indigo-100 text-indigo-600 flex items-center justify-center">
                             <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 4v16m8-8H4" /></svg>
                          </div>
                       </button>
                    ))
