  // Filter regular clients that are in watchlist OR have filing history for the selected year
  const trackedClients = useMemo(() => {
    return allClients.filter(c => {
      const isRegular = c.gstProfile?.regType === 'Regular';
      if (!isRegular) return false;

      const inWatchlist = watchlist.includes(c.id);
      const hasHistory = hasFilingInYear(c.id, selectedYear);

      return inWatchlist || hasHistory;
    });
