                                 </button>
                                 <button onClick={() => { setEditingPasswordId(client.id); setNewPasswordValue(client.gstProfile?.password || ''); }} className="p-1 text-slate-300 hover:text-amber-600 transition-colors opacity-0 group-hover/pass:opacity-100">
