                  <td colSpan={8} className="py-32 text-center">
                    <div className="flex flex-col items-center">
                      <p className="text-sm font-black uppercase tracking-[0.2em] text-slate-400">No entities added for GSTR-9 track</p>
                      <button onClick={() => setIsAddModalOpen(true)} className="mt-4 text-indigo-600 font-black uppercase text-[10px] tracking-widest hover:underline">+ Search & Add Client</button>
