    return list;
  }, [clients, search, statusFilter, getStatus]);

  const stats = useMemo(() => {
    const total = filteredClients.length;
    const filedCount = filteredClients.filter(c => c.gstProfile?.gstStatus === 'Active' && getStatus(c.id).cmp08).length;
    return { total, filedCount };
  }, [filteredClients, getStatus]);

  const handleExport = () => {
    const headers = ["S.No", "Trade Name", "Legal Name", "GSTIN", "User ID", "Password", "CMP-08 Status"].join(",");
    const rows = filteredClients.map((c, i) => [
      i + 1, c.tradeName, c.legalName, c.gstProfile?.gstin, c.gstProfile?.username, c.gstProfile?.password,
      getStatus(c.id).cmp08 ? "FILED" : "PENDING"
    ].join(",")).join("\n");
