  const handleExport = () => {
    const headers = ["S.No", "Name", "Father Name", "Pan No.", "Status", "Filing Date"].join(",");
    const rows = filteredClients.map((c, i) => {
      const st = getStatus(c.id);
      return [i + 1, c.legalName, c.itProfile?.fatherName || '---', c.itProfile?.pan, st.filed ? "FILED" : "PENDING", st.date || "N/A"].join(",");
    }).join("\n");
    const link = document.createElement('a');
    link.href = URL.createObjectURL(new Blob([headers + "\n" + rows], { type: 'text/csv' }));
    link.download = `ITR_Returns_AY_${selectedAY}.csv`;
    link.click();
