             </div>

             <div className="text-center space-y-1">
                <h3 className="text-xl font-black text-slate-900 uppercase tracking-tight">{activeFileTarget.client.legalName}</h3>
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">
