                      <td className="px-6 py-5 text-center">
                        <button onClick={() => toggleStatus(client.id, 'auditFiled')} className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest transition-all ${status.auditFiled ? 'bg-indigo-600 text-white shadow-lg' : 'bg-slate-100 text-slate-400 hover:bg-slate-200'}`}>
