      </div>
    );
  };

  return (
    <>
      <div 
        className={`fixed inset-0 z-[60] bg-slate-900/40 backdrop-blur-md transition-opacity duration-300 ${isOpen ? 'opacity-100' : 'opacity-0 pointer-events-none'}`} 
