import React, { useState, useEffect, useMemo } from 'react';
import { Client } from '../../../types';
import { mockBackend } from '../../../services/mockBackend';
import Loader from '../../../components/Loader';
import { useTaxAuditLogic } from './TAXAuditlogic';
import { YEARS } from '../GSTReturn/filinglogic/MonthlyFilingLogic';

const TAXAudit: React.FC = () => {
  const getPreviousFY = () => {
    const now = new Date();
    const currentMonth = now.getMonth();
    const currentYear = now.getFullYear();
    const startYear = currentMonth >= 3 ? currentYear - 1 : currentYear - 2;
    return `${startYear}-${(startYear + 1).toString().slice(-2)}`;
  };

  const [allClients, setAllClients] = useState<Client[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [selectedYear, setSelectedYear] = useState(getPreviousFY());

  // Add Client States
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [addSearch, setAddSearch] = useState('');
  const [pendingClientForAdd, setPendingClientForAdd] = useState<Client | null>(null);
  const [newCaName, setNewCaName] = useState('');

  const { getStatus, toggleStatus, updateCaName, updateDueDate, getDueDate, yearWatchlist, addToWatchlist, removeFromWatchlist } = useTaxAuditLogic(selectedYear);

  useEffect(() => {
    const fetch = async () => {
      setIsLoading(true);
      const data = await mockBackend.getClients();
      setAllClients(data);
      setIsLoading(false);
    };
    fetch();
  }, []);

  const trackedClients = useMemo(() => {
    return allClients.filter(c => yearWatchlist.includes(c.id));
  }, [allClients, yearWatchlist]);

  const filteredTracked = useMemo(() => {
    const s = search.toLowerCase();
    return trackedClients.filter(c => 
      (c.legalName || '').toLowerCase().includes(s) || 
      (c.itProfile?.pan || '').toLowerCase().includes(s) ||
      (c.gstProfile?.gstin || '').toLowerCase().includes(s)
    );
  }, [trackedClients, search]);

  const availableToAdd = useMemo(() => {
    const s = addSearch.toLowerCase();
    return allClients.filter(c => 
      !yearWatchlist.includes(c.id) && 
      ((c.legalName || '').toLowerCase().includes(s) || 
       (c.itProfile?.pan || '').toLowerCase().includes(s) || 
       (c.gstProfile?.gstin || '').toLowerCase().includes(s))
    );
  }, [allClients, yearWatchlist, addSearch]);

  const handleFinalizeAdd = () => {
