                    <p className="text-base font-black text-indigo-900 uppercase leading-tight">{pendingClientForAdd.legalName}</p>
                    <p className="text-[10px] text-indigo-600 font-mono mt-1 uppercase tracking-wider">{pendingClientForAdd.itProfile?.pan || pendingClientForAdd.gstProfile?.gstin}</p>
