                 </button>
              </div>

              {!pendingClientForAdd ? (
                <>
                  <div className="relative shrink-0">
                     <input type="text" placeholder="Search GST/IT Entity by Name, PAN or GSTIN..." value={addSearch} onChange={e => setAddSearch(e.target.value)}
                       className="w-full bg-slate-50 border border-slate-200 rounded-xl py-3.5 px-5 font-bold text-sm outline-none focus:ring-4 focus:ring-indigo-50 transition-all" />
                     <svg className="absolute right-5 top-1/2 -translate-y-1/2 h-5 w-5 text-slate-300" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
                  </div>
                  <div className="flex-1 max-h-[400px] overflow-y-auto space-y-2 pr-2 no-scrollbar">
                     {availableToAdd.length === 0 ? (
                       <p className="text-center py-10 text-slate-400 font-bold uppercase text-xs tracking-widest">No matching clients found in portfolios</p>
                     ) : (
                       availableToAdd.map(c => (
                         <button key={c.id} onClick={() => { setPendingClientForAdd(c); setNewCaName(''); }} 
                           className="w-full text-left p-4 rounded-2xl border border-slate-100 hover:border-indigo-600 hover:bg-indigo-50/50 transition-all flex items-center justify-between group">
                            <div className="min-w-0 flex-1">
                               <p className="text-sm font-black text-slate-900 uppercase group-hover:text-indigo-600 truncate">{c.legalName}</p>
                               <p className="text-[10px] text-slate-400 font-mono tracking-tight mt-1">{c.gstProfile?.gstin || c.itProfile?.pan || 'NO IDENTIFIER'}</p>
                            </div>
                            <svg className="h-5 w-5 text-slate-300 group-hover:text-indigo-600 shrink-0 ml-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M9 5l7 7-7 7" /></svg>
                         </button>
                       ))
                     )}
                  </div>
                </>
              ) : (
                <div className="space-y-6 animate-in slide-in-from-right-4 duration-300">
                  <div className="p-5 bg-indigo-50 rounded-2xl border border-indigo-100">
                    <p className="text-[10px] font-black text-indigo-400 uppercase tracking-widest mb-1">Entity Selection</p>
                    <p className="text-base font-black text-indigo-900 uppercase leading-tight">{pendingClientForAdd.legalName}</p>
                    <p className="text-[10px] text-indigo-600 font-mono mt-1 uppercase tracking-wider">{pendingClientForAdd.gstProfile?.gstin || pendingClientForAdd.itProfile?.pan}</p>
                  </div>

                  <div>
                    <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-2 block ml-1">CA Name</label>
                    <input 
                      autoFocus
                      type="text" 
                      placeholder="Enter CA Name for this audit" 
                      value={newCaName} 
                      onChange={e => setNewCaName(e.target.value)}
                      className="w-full bg-slate-50 border border-slate-200 rounded-xl py-4 px-5 font-black text-slate-900 outline-none focus:ring-4 focus:ring-indigo-100 transition-all" 
                    />
                  </div>

                  <div className="flex gap-4">
                    <button onClick={() => setPendingClientForAdd(null)} className="flex-1 py-4 bg-white border border-slate-200 text-slate-500 font-black uppercase tracking-widest text-[10px] rounded-xl hover:bg-slate-50">Back</button>
                    <button onClick={handleFinalizeAdd} className="flex-[2] py-4 bg-indigo-600 text-white font-black uppercase tracking-widest text-[10px] rounded-xl shadow-xl hover:bg-slate-900 transition-all">Add to Audit Tracking</button>
                  </div>
                </div>
              )}
           </div>
        </div>
      )}
    </div>
  );
};

export default TAXAudit;

import { useState, useCallback } from 'react';
import { YEARS } from '../GSTReturn/filinglogic/MonthlyFilingLogic';

export type BSStatus = 'Document Required' | 'In progress' | 'Ready' | 'Pending';

export interface AuditFinancialStatus {
  bsStatus: BSStatus;
  auditFiled: boolean;
  caName?: string;
  bsDate?: string;
  auditDate?: string;
}

const STORAGE_KEY_DATA = 'clientify_audit_fin_data_v4';
const STORAGE_KEY_WATCHLIST = 'clientify_audit_watchlist_v4';
const STORAGE_KEY_DATES = 'clientify_audit_due_dates_v1';

export const useTaxAuditLogic = (selectedYear: string) => {
  const [watchlist, setWatchlist] = useState<Record<string, string[]>>(() => {
    const saved = localStorage.getItem(STORAGE_KEY_WATCHLIST);
    return saved ? JSON.parse(saved) : {};
  });

  const [allData, setAllData] = useState<Record<string, Record<string, AuditFinancialStatus>>>(() => {
    const saved = localStorage.getItem(STORAGE_KEY_DATA);
    return saved ? JSON.parse(saved) : {};
  });

  const [dueDates, setDueDates] = useState<Record<string, string>>(() => {
    const saved = localStorage.getItem(STORAGE_KEY_DATES);
    return saved ? JSON.parse(saved) : {};
  });

  const yearWatchlist = watchlist[selectedYear] || [];

  const addToWatchlist = useCallback((clientId: string) => {
    setWatchlist(prev => {
      const next = { ...prev };
      // Find the index of the selected year to propagate forward
      const yearIdx = YEARS.indexOf(selectedYear);
      // YEARS is sorted latest first (e.g., [25-26, 24-25, 23-24])
      // Forward propagation means adding to all indices <= yearIdx
      for (let i = 0; i <= yearIdx; i++) {
        const y = YEARS[i];
        const current = next[y] || [];
        if (!current.includes(clientId)) {
          next[y] = [...current, clientId];
        }
      }
      localStorage.setItem(STORAGE_KEY_WATCHLIST, JSON.stringify(next));
      return next;
    });
  }, [selectedYear]);

  const removeFromWatchlist = useCallback((clientId: string) => {
    setWatchlist(prev => {
      const current = prev[selectedYear] || [];
      const next = { ...prev, [selectedYear]: current.filter(id => id !== clientId) };
      localStorage.setItem(STORAGE_KEY_WATCHLIST, JSON.stringify(next));
      return next;
    });
  }, [selectedYear]);

  const toggleAuditStatus = useCallback((clientId: string) => {
    setAllData(prev => {
      const yearData = { ...(prev[selectedYear] || {}) };
      const clientData = { ...(yearData[clientId] || { bsStatus: 'Pending', auditFiled: false }) };
      clientData.auditFiled = !clientData.auditFiled;
      if (clientData.auditFiled) {
        clientData.auditDate = new Date().toISOString().split('T')[0];
      } else {
        delete clientData.auditDate;
      }
      yearData[clientId] = clientData;
      const next = { ...prev, [selectedYear]: yearData };
      localStorage.setItem(STORAGE_KEY_DATA, JSON.stringify(next));
      return next;
    });
  }, [selectedYear]);

  const setBSStatus = useCallback((clientId: string, status: BSStatus) => {
    setAllData(prev => {
      const yearData = { ...(prev[selectedYear] || {}) };
      const clientData = { ...(yearData[clientId] || { bsStatus: 'Pending', auditFiled: false }) };
      clientData.bsStatus = status;
      if (status === 'Ready') {
        clientData.bsDate = new Date().toISOString().split('T')[0];
      }
      yearData[clientId] = clientData;
      const next = { ...prev, [selectedYear]: yearData };
      localStorage.setItem(STORAGE_KEY_DATA, JSON.stringify(next));
      return next;
    });
  }, [selectedYear]);

  const updateCaName = useCallback((clientId: string, name: string) => {
    setAllData(prev => {
      const yearData = { ...(prev[selectedYear] || {}) };
      const clientData = { ...(yearData[clientId] || { bsStatus: 'Pending', auditFiled: false }) };
      clientData.caName = name;
      yearData[clientId] = clientData;
      const next = { ...prev, [selectedYear]: yearData };
      localStorage.setItem(STORAGE_KEY_DATA, JSON.stringify(next));
      return next;
    });
  }, [selectedYear]);

  const getStatus = useCallback((clientId: string): AuditFinancialStatus => {
    return (allData[selectedYear] || {})[clientId] || { bsStatus: 'Pending', auditFiled: false };
  }, [allData, selectedYear]);

  const updateDueDate = (val: string) => {
    const next = { ...dueDates, [selectedYear]: val };
    setDueDates(next);
    localStorage.setItem(STORAGE_KEY_DATES, JSON.stringify(next));
  };

  const getDueDate = () => dueDates[selectedYear] || '';

  return { getStatus, toggleAuditStatus, setBSStatus, updateCaName, updateDueDate, getDueDate, yearWatchlist, addToWatchlist, removeFromWatchlist };
};

import React, { useState, useEffect, useMemo } from 'react';
import { Client } from '../../../types';
import { mockBackend } from '../../../services/mockBackend';
import Loader from '../../../components/Loader';
import { useTaxAuditLogic, BSStatus } from './TAXAuditlogic';
import { YEARS } from '../GSTReturn/filinglogic/MonthlyFilingLogic';

const TAXAudit: React.FC = () => {
  const getPreviousFY = () => {
    const now = new Date();
    const currentMonth = now.getMonth();
    const currentYear = now.getFullYear();
    const startYear = currentMonth >= 3 ? currentYear - 1 : currentYear - 2;
    return `${startYear}-${(startYear + 1).toString().slice(-2)}`;
  };

  const [allClients, setAllClients] = useState<Client[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [selectedYear, setSelectedYear] = useState(getPreviousFY());

  const [bsFilter, setBsFilter] = useState<'All' | BSStatus>('All');
  const [auditFilter, setAuditFilter] = useState<'All' | 'Filed' | 'Pending'>('All');
  const [isBsFilterOpen, setIsBsFilterOpen] = useState(false);
  const [isAuditFilterOpen, setIsAuditFilterOpen] = useState(false);

  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [addSearch, setAddSearch] = useState('');
  const [pendingClientForAdd, setPendingClientForAdd] = useState<Client | null>(null);
  const [newCaName, setNewCaName] = useState('');

  const [isViewModalOpen, setIsViewModalOpen] = useState(false);
  const [viewingClient, setViewingClient] = useState<Client | null>(null);
  const [editCaName, setEditCaName] = useState('');

  const { getStatus, toggleAuditStatus, setBSStatus, updateCaName, updateDueDate, getDueDate, yearWatchlist, addToWatchlist, removeFromWatchlist } = useTaxAuditLogic(selectedYear);

  useEffect(() => {
    const fetch = async () => {
      setIsLoading(true);
      const data = await mockBackend.getClients();
      setAllClients(data);
      setIsLoading(false);
    };
    fetch();
  }, []);

  const trackedClients = useMemo(() => {
    return allClients.filter(c => yearWatchlist.includes(c.id));
  }, [allClients, yearWatchlist]);

  const filteredTracked = useMemo(() => {
    const s = search.toLowerCase();
    let list = trackedClients.filter(c => 
      (c.legalName || '').toLowerCase().includes(s) || 
      (c.tradeName || '').toLowerCase().includes(s) || 
      (c.itProfile?.pan || '').toLowerCase().includes(s) ||
      (c.gstProfile?.gstin || '').toLowerCase().includes(s)
    );

    if (bsFilter !== 'All') list = list.filter(c => getStatus(c.id).bsStatus === bsFilter);
    if (auditFilter !== 'All') list = list.filter(c => auditFilter === 'Filed' ? getStatus(c.id).auditFiled : !getStatus(c.id).auditFiled);

    return list;
  }, [trackedClients, search, bsFilter, auditFilter, getStatus]);

  const availableToAdd = useMemo(() => {
    const s = addSearch.toLowerCase();
    return allClients.filter(c => 
      !yearWatchlist.includes(c.id) && 
      ((c.legalName || '').toLowerCase().includes(s) || 
       (c.tradeName || '').toLowerCase().includes(s) || 
       (c.itProfile?.pan || '').toLowerCase().includes(s) || 
       (c.gstProfile?.gstin || '').toLowerCase().includes(s))
    );
  }, [allClients, yearWatchlist, addSearch]);

  const handleFinalizeAdd = () => {
    if (!pendingClientForAdd) return;
    addToWatchlist(pendingClientForAdd.id);
    if (newCaName.trim()) {
      updateCaName(pendingClientForAdd.id, newCaName.trim());
    }
    setPendingClientForAdd(null);
    setNewCaName('');
    setIsAddModalOpen(false);
  };

  const cycleBSStatus = (clientId: string) => {
    const current = getStatus(clientId).bsStatus;
    const flow: BSStatus[] = ['Pending', 'Document Required', 'In progress', 'Ready'];
    const nextIdx = (flow.indexOf(current) + 1) % flow.length;
    setBSStatus(clientId, flow[nextIdx]);
  };

  if (isLoading) return <Loader />;

  return (
    <div className="flex flex-col h-full space-y-4 animate-in fade-in duration-500 max-w-full mx-auto w-full overflow-hidden">

      <div className="flex flex-col lg:flex-row items-center gap-4 bg-white p-3 rounded-[1.5rem] border border-slate-200 shadow-sm shrink-0">
        <div className="relative flex-1 w-full group">
          <input type="text" placeholder="Search entity, PAN or GSTIN..." value={search} onChange={e => setSearch(e.target.value)}
            className="w-full bg-slate-50 border-none rounded-xl py-3 pl-12 pr-4 font-bold text-sm text-slate-900 focus:ring-2 focus:ring-indigo-600/10 outline-none" />
          <svg className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-slate-400 group-focus-within:text-indigo-600 transition-colors" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
        </div>

        <div className="flex items-center gap-2 shrink-0">
          <button onClick={() => { setPendingClientForAdd(null); setAddSearch(''); setIsAddModalOpen(true); }} className="h-11 px-6 bg-indigo-600 text-white rounded-xl font-black text-xs uppercase tracking-widest shadow-lg hover:bg-slate-900 transition-all flex items-center gap-2">
            <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 4v16m8-8H4" /></svg>
            Add Client
          </button>
          <select value={selectedYear} onChange={e => setSelectedYear(e.target.value)} 
            className="bg-slate-50 border-none rounded-xl px-4 py-3 text-[11px] font-black uppercase tracking-widest text-slate-600 outline-none cursor-pointer">
            {YEARS.map(y => <option key={y} value={y}>FY {y}</option>)}
          </select>
          <div className="flex items-center bg-slate-50 rounded-xl px-4 py-3 gap-2 border border-transparent focus-within:border-indigo-100 transition-all">
            <span className="text-[9px] font-black text-slate-400 uppercase whitespace-nowrap">Due:</span>
            <input type="date" value={getDueDate()} onChange={e => updateDueDate(e.target.value)} className="bg-transparent border-none p-0 text-[11px] font-black text-slate-600 outline-none cursor-pointer uppercase" />
          </div>
        </div>
      </div>

      <div className="flex-1 bg-white rounded-[2rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col">
        <div className="overflow-x-auto no-scrollbar flex-1">
          <table className="w-full text-left border-collapse table-fixed min-w-[1250px]">
            <thead className="sticky top-0 z-20">
              <tr className="bg-slate-50 border-b border-slate-100">
                <th className="px-4 py-5 text-[14px] font-black uppercase tracking-widest text-slate-400 w-[60px]">S.No</th>
                <th className="px-4 py-5 text-[14px] font-black uppercase tracking-widest text-slate-400 w-[200px]">Trade Name</th>
                <th className="px-4 py-5 text-[14px] font-black uppercase tracking-widest text-slate-400 w-[200px]">Legal Name</th>
                <th className="px-4 py-5 text-[14px] font-black uppercase tracking-widest text-slate-400 w-[180px]">GSTIN/Pan</th>
                <th className="px-4 py-5 text-[14px] font-black uppercase tracking-widest text-slate-400 w-[150px]">Ca name</th>
                <th className="px-4 py-5 text-[14px] font-black uppercase tracking-widest text-slate-400 text-center w-[170px] relative">
                  <div className="flex items-center justify-center gap-1">
                    Balance Sheet
                    <button onClick={() => setIsBsFilterOpen(!isBsFilterOpen)} className="p-1 rounded bg-white border border-slate-200 shadow-sm transition-colors hover:bg-indigo-50"><svg className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M3 4a1 1 0 011-1h16a1 1 0 011 1v2.586a1 1 0 01-.293.707l-6.414 6.414a1 1 0 00-.293.707V17l-4 4v-6.586a1 1 0 00-.293-.707L3.293 7.293A1 1 0 013 6.586V4z" /></svg></button>
                  </div>
                  {isBsFilterOpen && (
                    <div className="absolute top-full left-1/2 -translate-x-1/2 mt-1 w-40 bg-white border border-slate-200 rounded-xl shadow-xl z-50 p-1 animate-in zoom-in-95">
                      {['All', 'Document Required', 'In progress', 'Ready', 'Pending'].map(f => (
                        <button key={f} onClick={() => { setBsFilter(f as any); setIsBsFilterOpen(false); }} className={`w-full text-left px-3 py-2 text-[10px] font-black uppercase rounded-lg ${bsFilter === f ? 'bg-indigo-600 text-white' : 'hover:bg-slate-50'}`}>{f}</button>
