    removeFromWatchlist,
    hasFilingInYear,
    is9CApplicable,
    updateDueDate,
    getDueDate
  } = useGSTR9Logic(selectedYear);

  const fetchClients = async () => {
    setIsLoading(true);
    try {
      const data = await mockBackend.getClients();
      setAllClients(data);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchClients();
