      (c.legalName || '').toLowerCase().includes(s) || 
      (c.tradeName || '').toLowerCase().includes(s) || 
      (c.gstProfile?.gstin && c.gstProfile.gstin.toLowerCase().includes(s)) || 
      (c.mobile || '').includes(s)
    );

    if (gstr9Filter !== 'All') list = list.filter(c => gstr9Filter === 'Filed' ? getStatus(c.id).gstr9 : !getStatus(c.id).gstr9);
    if (gstr9cFilter !== 'All') list = list.filter(c => !is9CApplicable(c.id) ? false : (gstr9cFilter === 'Filed' ? getStatus(c.id).gstr9c : !getStatus(c.id).gstr9c));

    return list;
  }, [trackedClients, search, gstr9Filter, gstr9cFilter, getStatus, is9CApplicable]);

  const clientsAvailableToAdd = useMemo(() => {
    return allClients.filter(c => 
      c.gstProfile?.regType === 'Regular' && 
      !watchlist.includes(c.id) &&
      ((c.legalName || '').toLowerCase().includes(addSearch.toLowerCase()) || 
