                  <div className="flex items-center justify-center gap-1">
                    GSTR-9
                    <button onClick={() => setActiveHeaderFilter(activeHeaderFilter === 'gstr9' ? null : 'gstr9')} className="p-1 rounded bg-white border border-slate-200"><svg className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M3 4a1 1 0 011-1h16a1 1 0 011 1v2.586a1 1 0 01-.293.707l-6.414 6.414a1 1 0 00-.293.707V17l-4 4v-6.586a1 1 0 00-.293-.707L3.293 7.293A1 1 0 013 6.586V4z" /></svg></button>
                  </div>
                  {activeHeaderFilter === 'gstr9' && (
                    <div className="absolute top-full left-1/2 -translate-x-1/2 mt-1 w-32 bg-white border border-slate-200 rounded-xl shadow-xl z-50 p-1 animate-in zoom-in-95">
                      {['All', 'Filed', 'Pending'].map(f => (
                        <button key={f} onClick={() => { setGstr9Filter(f as any); setActiveHeaderFilter(null); }} className={`w-full text-left px-3 py-2 text-[10px] font-black uppercase rounded-lg ${gstr9Filter === f ? 'bg-indigo-600 text-white' : 'hover:bg-slate-50'}`}>{f}</button>
                      ))}
                    </div>
                  )}
                </th>

                <th className="px-4 py-5 text-[14px] font-black uppercase tracking-widest text-slate-400 text-center w-[120px] relative">
                  <div className="flex items-center justify-center gap-1">
                    GSTR-9C
                    <button onClick={() => setActiveHeaderFilter(activeHeaderFilter === 'gstr9c' ? null : 'gstr9c')} className="p-1 rounded bg-white border border-slate-200"><svg className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M3 4a1 1 0 011-1h16a1 1 0 011 1v2.586a1 1 0 01-.293.707l-6.414 6.414a1 1 0 00-.293.707V17l-4 4v-6.586a1 1 0 00-.293-.707L3.293 7.293A1 1 0 013 6.586V4z" /></svg></button>
                  </div>
                  {activeHeaderFilter === 'gstr9c' && (
                    <div className="absolute top-full left-1/2 -translate-x-1/2 mt-1 w-32 bg-white border border-slate-200 rounded-xl shadow-xl z-50 p-1 animate-in zoom-in-95">
                      {['All', 'Filed', 'Pending'].map(f => (
                        <button key={f} onClick={() => { setGstr9cFilter(f as any); setActiveHeaderFilter(null); }} className={`w-full text-left px-3 py-2 text-[10px] font-black uppercase rounded-lg ${gstr9cFilter === f ? 'bg-indigo-600 text-white' : 'hover:bg-slate-50'}`}>{f}</button>
                      ))}
                    </div>
                  )}
                </th>

                <th className="px-4 py-5 text-[14px] font-black uppercase tracking-widest text-slate-400 text-right w-[120px]">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredDisplayList.map((client, idx) => {
                const status = getStatus(client.id);
                const is9cApp = is9CApplicable(client.id);

                return (
                  <tr key={client.id} className="group hover:bg-slate-50/50 transition-all text-[12px]">
                    <td className="px-4 py-5 font-black text-slate-300">{(idx + 1).toString().padStart(2, '0')}</td>
                    <td className="px-4 py-5 font-black text-slate-900 truncate uppercase">{client.tradeName || '---'}</td>
                    <td className="px-4 py-5 font-bold text-slate-500 truncate uppercase">{client.legalName}</td>
                    <td className="px-4 py-5 font-black text-indigo-600 font-mono tracking-widest uppercase">{client.gstProfile?.gstin}</td>

                    <td className="px-4 py-5 text-center">
                       <button onClick={() => toggleStatus(client.id, 'gstr9')} className={`px-4 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest transition-all ${status.gstr9 ? 'bg-emerald-100 text-emerald-700' : 'bg-slate-100 text-slate-400 hover:bg-slate-200'}`}>
                         {status.gstr9 ? 'Filed' : 'Pending'}
                       </button>
                    </td>

                    <td className="px-4 py-5 text-center">
                       {!is9cApp ? <span className="text-[9px] font-black text-slate-300 uppercase tracking-widest">N/A</span> : (
                         <button onClick={() => toggleStatus(client.id, 'gstr9c')} className={`px-4 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest transition-all ${status.gstr9c ? 'bg-indigo-100 text-indigo-700' : 'bg-slate-100 text-slate-400 hover:bg-slate-200'}`}>
                           {status.gstr9c ? 'Filed' : 'Pending'}
                         </button>
                       )}
                    </td>

                    <td className="px-4 py-5 text-right whitespace-nowrap">
                       <div className="flex items-center justify-end gap-2">
                          <button onClick={() => { setSelectedClient(client); setIsDetailModalOpen(true); }} className="h-8 w-8 rounded-lg bg-slate-50 border border-slate-200 text-slate-400 hover:text-indigo-600 transition-all flex items-center justify-center">
                             <svg className="h-4.5 w-4.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7S1.732 16.057.458 10z" /></svg>
                          </button>
                          <button onClick={() => { if(confirm(`Remove ${client.legalName} from tracking matrix?`)) removeFromWatchlist(client.id); }} className="h-8 w-8 rounded-lg bg-slate-50 border border-slate-200 text-slate-400 hover:text-red-600 transition-all flex items-center justify-center">
                             <svg className="h-4.5 w-4.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                          </button>
                       </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>

      {/* DETAIL MODAL WITH TOGGLE 9C APPLICABILITY */}
      {isDetailModalOpen && selectedClient && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center bg-slate-900/60 backdrop-blur-md p-4 animate-in fade-in duration-200">
           <div className="w-full max-w-2xl bg-white rounded-[2.5rem] shadow-2xl flex flex-col overflow-hidden animate-in zoom-in-95">
              <div className="px-8 py-6 bg-slate-50 border-b border-slate-100 flex items-center justify-between shrink-0">
                 <h3 className="text-xl font-black text-slate-900 uppercase tracking-tight">Annual Matrix Record</h3>
                 <button onClick={() => setIsDetailModalOpen(false)} className="h-10 w-10 flex items-center justify-center rounded-xl hover:bg-slate-100 transition-colors"><svg className="h-6 w-6 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6" /></svg></button>
              </div>

              <div className="p-10 space-y-10 overflow-y-auto no-scrollbar">
                 <div className="grid grid-cols-2 gap-x-12 gap-y-6">
                    <div className="col-span-2 p-6 bg-indigo-50 rounded-2xl border border-indigo-100">
                       <p className="text-[10px] font-black text-indigo-400 uppercase tracking-widest mb-1">Entity Details</p>
                       <h4 className="text-lg font-black text-indigo-900 uppercase leading-tight">{selectedClient.legalName}</h4>
                       <p className="text-xs font-black text-indigo-600 font-mono mt-1">{selectedClient.gstProfile?.gstin}</p>
                    </div>
                    <div><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Portal User ID</p><p className="text-sm font-black text-slate-900">{selectedClient.gstProfile?.username}</p></div>
                    <div><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Contact</p><p className="text-sm font-black text-slate-900">{selectedClient.mobile}</p></div>
                 </div>

                 <div className="pt-8 border-t border-slate-100 space-y-6">
                    <h4 className="text-[10px] font-black uppercase tracking-[0.25em] text-indigo-600 mb-2">Compliance Configuration</h4>
                    <div className="flex items-center justify-between p-5 bg-slate-50 rounded-2xl border border-slate-100 group">
                       <div className="space-y-0.5">
                          <p className="text-sm font-black text-slate-900 uppercase tracking-tight">GSTR-9C Applicability</p>
                          <p className="text-[10px] font-medium text-slate-400 uppercase">Is annual audit required for this entity?</p>
                       </div>
                       <button 
                         onClick={() => update9CApplicability(selectedClient.id, !is9CApplicable(selectedClient.id))}
                         className={`px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${is9CApplicable(selectedClient.id) ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-100' : 'bg-slate-200 text-slate-500'}`}
                       >
                         {is9CApplicable(selectedClient.id) ? 'Applicable' : 'Exempted'}
                       </button>
                    </div>
                 </div>
              </div>

              <div className="p-8 border-t border-slate-100 bg-slate-50/50 flex gap-4 shrink-0">
                <button onClick={() => setIsDetailModalOpen(false)} className="flex-1 py-4 text-slate-500 font-black uppercase tracking-widest text-[10px] bg-white border border-slate-200 rounded-xl">Close View</button>
              </div>
           </div>
        </div>
      )}

      {/* ADD CLIENT MODAL WITH FORWARD PROPAGATION */}
      {isAddModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-900/60 backdrop-blur-md p-4">
          <div className="w-full max-w-md bg-white rounded-[2rem] shadow-2xl p-8 flex flex-col space-y-6 animate-in zoom-in-95">
            <div className="flex items-center justify-between shrink-0">
               <h3 className="text-xl font-black text-slate-900 uppercase tracking-tight">Add to Matrix Matrix</h3>
               <button onClick={() => { setIsAddModalOpen(false); setPendingClientToAdd(null); }} className="h-10 w-10 flex items-center justify-center rounded-xl hover:bg-slate-100 transition-colors"><svg className="h-6 w-6 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6" /></svg></button>
            </div>

            {!pendingClientToAdd ? (
              <>
                <div className="relative">
                  <input type="text" placeholder="Search available regular clients..." value={addSearch} onChange={e => setAddSearch(e.target.value)}
                    className="w-full bg-slate-50 border border-slate-200 rounded-xl py-3 px-4 font-bold text-sm outline-none focus:ring-4 focus:ring-indigo-50 transition-all" />
                </div>
                <div className="max-h-60 overflow-y-auto space-y-2 no-scrollbar pr-1">
                  {clientsAvailableToAdd.map(c => (
                    <button key={c.id} onClick={() => setPendingClientToAdd(c)} className="w-full text-left p-4 rounded-xl border border-slate-100 hover:border-indigo-600 hover:bg-indigo-50/50 transition-all flex items-center justify-between group">
                      <div>
                         <p className="text-xs font-black text-slate-900 uppercase group-hover:text-indigo-600">{c.tradeName || c.legalName}</p>
                         <p className="text-[10px] text-slate-400 font-mono tracking-tighter mt-1">{c.gstProfile?.gstin}</p>
                      </div>
                      <svg className="h-5 w-5 text-slate-200 group-hover:text-indigo-600" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M9 5l7 7-7 7" /></svg>
                    </button>
                  ))}
                </div>
              </>
            ) : (
              <div className="space-y-6 animate-in slide-in-from-right-4">
                <div className="p-5 bg-indigo-50 rounded-2xl border border-indigo-100">
                  <p className="text-[10px] font-black text-indigo-400 uppercase tracking-widest mb-1">Active Selection</p>
                  <p className="text-base font-black text-indigo-900 uppercase leading-tight">{pendingClientToAdd.legalName}</p>
                  <p className="text-[10px] text-indigo-600 font-mono mt-1 uppercase tracking-wider">{pendingClientToAdd.gstProfile?.gstin}</p>
                </div>

                <div className="space-y-4">
                  <label className="flex items-center gap-3 cursor-pointer group">
                    <div className="relative flex items-center">
                       <input type="checkbox" checked={nineCApplicableInput === 'true'} onChange={e => setNineCApplicableInput(e.target.checked ? 'true' : 'false')} className="h-5 w-5 rounded-md border-slate-200 accent-indigo-600 cursor-pointer" />
                    </div>
                    <span className="text-xs font-black text-slate-600 uppercase tracking-tight">Enable GSTR-9C Matrix?</span>
                  </label>

                  <div className="p-4 bg-amber-50 rounded-xl border border-amber-100">
                     <p className="text-[9px] font-bold text-amber-600 leading-normal uppercase">
                        Client will be added to FY {selectedYear} and all subsequent Assessment Years.
                     </p>
                  </div>
                </div>

                <div className="flex gap-3">
                  <button onClick={() => setPendingClientToAdd(null)} className="flex-1 py-4 bg-white border border-slate-200 text-slate-500 rounded-xl font-black uppercase text-[10px] tracking-widest">Back</button>
                  <button onClick={() => { addToWatchlist(pendingClientToAdd.id, nineCApplicableInput === 'true'); setIsAddModalOpen(false); }} className="flex-[2] py-4 bg-indigo-600 text-white rounded-xl font-black uppercase text-[10px] tracking-widest shadow-xl hover:bg-slate-900 transition-all">Add to Records</button>
                </div>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

export default GSTR9_9C;
